from pathlib import Path

web = Path('apps/web/src/main.tsx')
w = web.read_text()
start = w.index('function ResourcePage(')
end = w.index('function CustomerForm(', start)
new_resource = r'''function ResourcePage({kind,user:_user}:{kind:ResourceKind;user:User}){const m=meta[kind];const [rows,setRows]=useState<any[]>([]);const [q,setQ]=useState('');const [open,setOpen]=useState(false);const [error,setError]=useState('');const [loading,setLoading]=useState(false);const load=()=>{setLoading(true);setError('');api(m.endpoint+(q?`?q=${encodeURIComponent(q)}`:'')).then(x=>setRows(Array.isArray(x)?x:[])).catch(e=>setError(e.message)).finally(()=>setLoading(false))};useEffect(()=>{void load();},[q]);const canAdd=['customers','routers','servers'].includes(kind);const remove=async(id:string,name:string)=>{if(!window.confirm(`حذف الخادم «${name}»؟`))return;try{await api(`/api/v1/admin/servers/hosts/${id}`,{method:'DELETE'});await load()}catch(e:any){setError(e.message)}};const confirmPayment=async(id:string)=>{if(!window.confirm('تأكيد استلام الدفع لهذا الطلب؟ سيتم تحويل الطلب إلى مدفوع وتشغيل التجهيز تلقائيًا.'))return;setLoading(true);setError('');try{await api(`/api/v1/admin/payments/${id}/confirm`,{method:'POST',body:JSON.stringify({})});await load()}catch(e:any){setError(e.message)}finally{setLoading(false)}};const rejectPayment=async(id:string)=>{const reason=window.prompt('سبب رفض الدفع:','لم يتم استلام/مطابقة التحويل');if(reason===null)return;setLoading(true);setError('');try{await api(`/api/v1/admin/payments/${id}/reject`,{method:'POST',body:JSON.stringify({reason})});await load()}catch(e:any){setError(e.message)}finally{setLoading(false)}};return <div className="page"><Heading title={m.title} sub={kind==='payments'?'مراجعة وتأكيد المدفوعات اليدوية من هنا.':'بيانات حقيقية من الـAPI.'} onAdd={canAdd?()=>setOpen(true):undefined}/><section className="panel table-panel"><div className="toolbar"><label className="search wide"><Search size={16}/><input value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>e.key==='Enter'&&load()} placeholder="بحث..."/></label><button className="secondary-button" onClick={load} disabled={loading}><RefreshCw size={15}/> تحديث</button></div>{error&&<div className="alert error">{error}</div>}<div className="table-wrap"><table><thead><tr>{m.cols.map((x:string)=><th key={x}>{x}</th>)}{kind==='servers'&&<th>إجراءات</th>}{kind==='payments'&&<th>إجراءات</th>}</tr></thead><tbody>{loading?<tr><td className="empty" colSpan={m.cols.length+((kind==='servers'||kind==='payments')?1:0)}>جاري التحميل...</td></tr>:rows.length===0?<tr><td className="empty" colSpan={m.cols.length+((kind==='servers'||kind==='payments')?1:0)}>لا توجد بيانات</td></tr>:rows.map((r:any,i:number)=><tr key={r.id||i}>{m.keys.map((k:string)=><td key={k}>{k.includes('minor')?money(r[k]):k.endsWith('_at')||k.includes('date')?date(r[k]):['status','connectivity','state','lifecycle_status','health_status'].includes(k)?<span className="badge">{label(r[k])}</span>:String(r[k]??'—')}</td>)}{kind==='servers'&&<td><button className="danger-button" type="button" onClick={()=>remove(r.id,r.name||r.address||'هذا الخادم')}>حذف</button></td>}{kind==='payments'&&<td><div className="row-actions">{['INITIATED','PENDING'].includes(String(r.status))&&<><button className="primary-button compact" type="button" onClick={()=>void confirmPayment(r.id)} disabled={loading}>تأكيد الدفع</button><button className="danger-button" type="button" onClick={()=>void rejectPayment(r.id)} disabled={loading}>رفض</button></>}{r.status==='SUCCEEDED'&&<span className="badge success-badge">تم التأكيد</span>}{r.status==='FAILED'&&<span className="badge">مرفوض</span>}</div></td>}</tr>)}</tbody></table></div></section>{open&&kind==='customers'&&<CustomerForm onClose={()=>setOpen(false)} onDone={()=>{setOpen(false);load()}}/>}{open&&kind==='routers'&&<RouterForm onClose={()=>setOpen(false)} onDone={()=>{setOpen(false);load()}}/>}{open&&kind==='servers'&&<ServerForm onClose={()=>setOpen(false)} onDone={()=>{setOpen(false);load()}}/>}</div>}
'''
w = w[:start] + new_resource + w[end:]
web.write_text(w)
